import{_ as e,o as r,c as d,aB as a}from"./chunks/framework.CJnWeT0n.js";const u=JSON.parse('{"title":"Feature Coverage","description":"","frontmatter":{},"headers":[],"relativePath":"feature-coverage.md","filePath":"feature-coverage.md","lastUpdated":null}'),i={name:"feature-coverage.md"};function l(s,t,n,g,o,h){return r(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="Feature-Coverage" tabindex="-1">Feature Coverage <a class="header-anchor" href="#Feature-Coverage" aria-label="Permalink to &quot;Feature Coverage {#Feature-Coverage}&quot;">​</a></h1><p>This page summarizes the supported surface. The repository root <code>FEATURES_COVERAGE.md</code> remains the detailed tracking file for implementation notes and intentionally omitted edge cases.</p><h2 id="Core-NATS" tabindex="-1">Core NATS <a class="header-anchor" href="#Core-NATS" aria-label="Permalink to &quot;Core NATS {#Core-NATS}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Feature</th><th style="text-align:right;">Status</th><th style="text-align:right;">Notes</th></tr></thead><tbody><tr><td style="text-align:right;">Connect handshake</td><td style="text-align:right;">Supported</td><td style="text-align:right;">Includes authentication fields, client name, no echo, TLS requirements, and server INFO parsing.</td></tr><tr><td style="text-align:right;">Publish and subscribe</td><td style="text-align:right;">Supported</td><td style="text-align:right;">Includes wildcards, queue groups, headers, max payload checks, and per-subscription pending limits.</td></tr><tr><td style="text-align:right;">Request reply</td><td style="text-align:right;">Supported</td><td style="text-align:right;">Uses temporary inbox subscriptions and maps no-responder status to <code>NoRespondersError</code>.</td></tr><tr><td style="text-align:right;">Flush and ping</td><td style="text-align:right;">Supported</td><td style="text-align:right;">Uses PING/PONG synchronization.</td></tr><tr><td style="text-align:right;">Drain and close</td><td style="text-align:right;">Supported</td><td style="text-align:right;">Drains subscriptions and reports cleanup failures.</td></tr><tr><td style="text-align:right;">Automatic reconnect</td><td style="text-align:right;">Supported</td><td style="text-align:right;">Reconnects in the background, replays subscriptions, and flushes bounded pending publishes.</td></tr><tr><td style="text-align:right;">Discovered servers</td><td style="text-align:right;">Supported</td><td style="text-align:right;">Server-discovered URLs are retained for reconnects.</td></tr><tr><td style="text-align:right;">Slow consumer handling</td><td style="text-align:right;">Supported</td><td style="text-align:right;">Drops over-limit messages and reports <code>SlowConsumerError</code>.</td></tr><tr><td style="text-align:right;">WebSocket transport</td><td style="text-align:right;">Not implemented</td><td style="text-align:right;">Planned only if there is clear demand.</td></tr></tbody></table><h2 id="TLS-And-Security" tabindex="-1">TLS And Security <a class="header-anchor" href="#TLS-And-Security" aria-label="Permalink to &quot;TLS And Security {#TLS-And-Security}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Feature</th><th style="text-align:right;">Status</th><th style="text-align:right;">Notes</th></tr></thead><tbody><tr><td style="text-align:right;">TLS-first handshake</td><td style="text-align:right;">Supported</td><td style="text-align:right;"><code>tls://</code> defaults to TLS before INFO.</td></tr><tr><td style="text-align:right;">INFO-first TLS upgrade</td><td style="text-align:right;">Supported</td><td style="text-align:right;">Use <code>tls_first=false</code> for deployments that require it.</td></tr><tr><td style="text-align:right;">CA and client certificates</td><td style="text-align:right;">Supported</td><td style="text-align:right;"><code>tls_ca_path</code>, <code>tls_cert_path</code>, and <code>tls_key_path</code>.</td></tr><tr><td style="text-align:right;">Disable certificate verification</td><td style="text-align:right;">Supported</td><td style="text-align:right;"><code>tls_verify=false</code>; intended only for trusted environments.</td></tr><tr><td style="text-align:right;">nkeys and JWT credentials</td><td style="text-align:right;">Not implemented</td><td style="text-align:right;">Authentication currently covers token and user/password credentials.</td></tr></tbody></table><h2 id="JetStream" tabindex="-1">JetStream <a class="header-anchor" href="#JetStream" aria-label="Permalink to &quot;JetStream {#JetStream}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Feature</th><th style="text-align:right;">Status</th><th style="text-align:right;">Notes</th></tr></thead><tbody><tr><td style="text-align:right;">Typed stream configs</td><td style="text-align:right;">Supported</td><td style="text-align:right;">Mirrors known stream schema fields with Julia structs and EnumX enums.</td></tr><tr><td style="text-align:right;">Typed consumer configs</td><td style="text-align:right;">Supported</td><td style="text-align:right;">Mirrors known consumer schema fields with Julia structs and EnumX enums.</td></tr><tr><td style="text-align:right;">Raw config dictionaries</td><td style="text-align:right;">Supported</td><td style="text-align:right;">Escape hatch for newer server fields.</td></tr><tr><td style="text-align:right;">Stream CRUD and list APIs</td><td style="text-align:right;">Supported</td><td style="text-align:right;">Includes pagination.</td></tr><tr><td style="text-align:right;">Consumer CRUD and list APIs</td><td style="text-align:right;">Supported</td><td style="text-align:right;">Includes server-version-aware create subjects.</td></tr><tr><td style="text-align:right;">Publish acknowledgements</td><td style="text-align:right;">Supported</td><td style="text-align:right;"><code>js_publish</code> returns <code>PubAck</code>.</td></tr><tr><td style="text-align:right;">Pull consumers</td><td style="text-align:right;">Supported</td><td style="text-align:right;">Durable and ephemeral consumers, batch fetch, and expiration handling.</td></tr><tr><td style="text-align:right;">Push consumers</td><td style="text-align:right;">Supported</td><td style="text-align:right;">Queue groups, callbacks, and manual or automatic acknowledgement.</td></tr><tr><td style="text-align:right;">Message acknowledgements</td><td style="text-align:right;">Supported</td><td style="text-align:right;"><code>ack</code>, <code>ack_sync</code>, <code>nak</code>, <code>in_progress</code>, and <code>term</code>.</td></tr><tr><td style="text-align:right;">Message get</td><td style="text-align:right;">Supported</td><td style="text-align:right;">Sequence, last by subject, next by subject, and direct get.</td></tr><tr><td style="text-align:right;">Ordered consumers</td><td style="text-align:right;">Not implemented</td><td style="text-align:right;">Can be added later if needed.</td></tr><tr><td style="text-align:right;">Object store</td><td style="text-align:right;">Not implemented</td><td style="text-align:right;">Outside the current high-value surface.</td></tr></tbody></table><h2 id="KeyValue" tabindex="-1">KeyValue <a class="header-anchor" href="#KeyValue" aria-label="Permalink to &quot;KeyValue {#KeyValue}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Feature</th><th style="text-align:right;">Status</th><th style="text-align:right;">Notes</th></tr></thead><tbody><tr><td style="text-align:right;">Bucket create/open/delete</td><td style="text-align:right;">Supported</td><td style="text-align:right;">Backed by JetStream streams.</td></tr><tr><td style="text-align:right;">Put/create/update</td><td style="text-align:right;">Supported</td><td style="text-align:right;">Includes optimistic revision checks.</td></tr><tr><td style="text-align:right;">Get by latest or revision</td><td style="text-align:right;">Supported</td><td style="text-align:right;">Direct reads are used when bucket direct access is enabled.</td></tr><tr><td style="text-align:right;">Delete and purge</td><td style="text-align:right;">Supported</td><td style="text-align:right;">Uses KeyValue operation headers.</td></tr><tr><td style="text-align:right;">History and keys</td><td style="text-align:right;">Supported</td><td style="text-align:right;">Implemented through pull consumers.</td></tr><tr><td style="text-align:right;">Watch</td><td style="text-align:right;">Supported</td><td style="text-align:right;">Implemented through push consumers.</td></tr></tbody></table>',10)])])}const y=e(i,[["render",l]]);export{u as __pageData,y as default};
